-- Rollback-only badge authority proof for the exact legacy-to-Pro continuation.
-- Run after the reviewed bridge/app/legal activation on the synthetic baseline.
-- All players/results are synthetic; only public binding metadata is reused.
begin;
set local request.jwt.claims='{"role":"service_role","sub":"local-consolidated-admin"}';
set local lock_timeout='5s';
set local statement_timeout='2min';
select pg_temp.fd_assert(inet_server_addr()='127.0.0.1'::inet and inet_server_port()=56623 and current_database()='consolidated_rehearsal','badge bridge test requires attested synthetic loopback');
select pg_temp.fd_assert(not exists(select 1 from public.players where clerk_user_id not like 'local-consolidated-%'),'badge bridge test rejects non-synthetic identities');

create temporary table bridge_badge_season as
select membership.season_id, season.name as source_season_name
from public.leaderboard_tournament_season_memberships membership
join public.leaderboard_seasons season on season.id=membership.season_id
where membership.tournament_id=pg_temp.fd_id('event',1)
  and membership.qualifying_event_number=1 and membership.scored_at is not null and membership.voided_at is null;
select pg_temp.fd_assert((select count(*)=1 from bridge_badge_season),'badge proof requires one preserved genuine legacy event');
select pg_temp.fd_assert((select official_bracket_type='main' and finalized_at is null and is_active from public.leaderboard_seasons where id=(select season_id from bridge_badge_season)),'bridge must not reclassify or prematurely finalize stored legacy season');
select pg_temp.fd_assert(ironclad_private.leaderboard_official_season_role((select season_id from bridge_badge_season))='pro','activated bridge must provide the explicit Pro official role');
select pg_temp.fd_assert(not exists(select 1 from public.leaderboard_season_champions where season_id=(select season_id from bridge_badge_season)),'one-event bridge must not manufacture a champion');
select pg_temp.fd_assert(not exists(select 1 from public.player_badge_awards where source_type='season' and source_id=(select season_id from bridge_badge_season)),'bridge activation must not manufacture season awards');
select pg_temp.fd_assert(season_campaigner_count=0 and podium_finish_count=0 and champion_finish_count=0,'active continued season has no final season badge authority')
from public.get_player_badge_season_summary(pg_temp.fd_id('Main-player',0,1));
select pg_temp.fd_assert(main_championship_count=1 and first_main_championship_bracket_type='main','legacy Elite championship keeps its original main source')
from public.get_player_badge_tournament_prestige_summary(pg_temp.fd_id('Main-player',0,1));

-- Seed one already legitimately earned synthetic legacy award and its reveal.
-- This is a fixture, never an award generated by bridge activation.
insert into public.player_badge_awards(id,player_id,badge_slug,source_type,source_id,source_metadata,unlocked_at,original_unlocked_at,standard_reveal_seen_at,created_at)
select pg_temp.fd_id('bridge-preserved-elite-award',1),pg_temp.fd_id('Main-player',0,1),'elite-champion','tournament',pg_temp.fd_id('event',1),
  '{"evaluator":"division-championship","bracketType":"main","eventType":"tournament_win"}'::jsonb,
  settlement.settled_at,settlement.settled_at,settlement.settled_at,settlement.settled_at
from public.leaderboard_division_settlements settlement where settlement.tournament_bracket_id=pg_temp.fd_id('Main',1);
insert into public.player_badge_reveals(id,player_badge_award_id,player_id,revealed_at,created_at)
select pg_temp.fd_id('bridge-preserved-elite-reveal',1),award.id,award.player_id,award.standard_reveal_seen_at,award.created_at
from public.player_badge_awards award where award.id=pg_temp.fd_id('bridge-preserved-elite-award',1);
insert into public.notifications(id,recipient_clerk_user_id,type,title,message,tournament_id,metadata,event_key,email_attempt_count,read_at)
select pg_temp.fd_id('bridge-preserved-elite-notification',1),player.clerk_user_id,'badge_unlocked','Elite Champion','Synthetic already-earned legacy award',pg_temp.fd_id('event',1),
  jsonb_build_object('awardId',award.id,'badgeSlug','elite-champion'),'local-consolidated-bridge-elite-history',null,award.created_at
from public.player_badge_awards award join public.players player on player.id=award.player_id where award.id=pg_temp.fd_id('bridge-preserved-elite-award',1);
create temporary table bridge_badge_history as
select
  (select to_jsonb(award) from public.player_badge_awards award where award.id=pg_temp.fd_id('bridge-preserved-elite-award',1)) as award,
  (select to_jsonb(reveal) from public.player_badge_reveals reveal where reveal.id=pg_temp.fd_id('bridge-preserved-elite-reveal',1)) as reveal,
  (select to_jsonb(notification) from public.notifications notification where notification.id=pg_temp.fd_id('bridge-preserved-elite-notification',1)) as notification,
  (select jsonb_agg(to_jsonb(event) order by event.id) from public.leaderboard_point_events event where event.tournament_id=pg_temp.fd_id('event',1)) as point_events,
  (select to_jsonb(membership) from public.leaderboard_tournament_season_memberships membership where membership.tournament_id=pg_temp.fd_id('event',1)) as membership,
  (select jsonb_agg(to_jsonb(settlement) order by settlement.tournament_bracket_id) from public.leaderboard_division_settlements settlement join public.tournament_brackets bracket on bracket.id=settlement.tournament_bracket_id where bracket.tournament_id=pg_temp.fd_id('event',1)) as settlements;

select set_config('ironclad.test_model','four_division_v1',true);
do $$ declare event integer; begin
  for event in 2..6 loop
    if event<6 then perform pg_temp.fd_create(event,'Main'); end if;
    perform pg_temp.fd_create(event,'Pro');
    if event<6 then
      perform pg_temp.fd_play(event,'Main');
      perform pg_temp.fd_assert((select status='in_progress' from public.tournaments where id=pg_temp.fd_id('event',event)),'sibling Main must not prematurely complete the parent before genuine Pro finishes');
      perform pg_temp.fd_assert(not exists(select 1 from public.leaderboard_tournament_season_memberships where tournament_id=pg_temp.fd_id('event',event) and qualifying_event_number is not null),'sibling Main must not consume an official Pro slot');
    end if;
    perform pg_temp.fd_play(event,'Pro');
    perform pg_temp.fd_assert((select membership.season_id=(select season_id from bridge_badge_season) and membership.qualifying_event_number=event and membership.scored_at is not null and membership.voided_at is null from public.leaderboard_tournament_season_memberships membership where membership.tournament_id=pg_temp.fd_id('event',event)),'genuine Pro event did not continue the same factual season slot '||event);
    if event<6 then
      perform pg_temp.fd_assert((select finalized_at is null from public.leaderboard_seasons where id=(select season_id from bridge_badge_season)),'continued season finalized before six genuine events');
      perform pg_temp.fd_assert(not exists(select 1 from public.leaderboard_season_champions where season_id=(select season_id from bridge_badge_season)),'continued season acquired an early champion');
      perform pg_temp.fd_assert((select season_campaigner_count=0 and podium_finish_count=0 and champion_finish_count=0 from public.get_player_badge_season_summary(pg_temp.fd_id('Pro-player',0,1))),'continued season acquired early season badge authority');
    end if;
  end loop;
end $$;
select pg_temp.fd_assert((select official_bracket_type='main' and finalized_at is not null and not is_active from public.leaderboard_seasons where id=(select season_id from bridge_badge_season)),'six factual events must finalize without relabeling stored legacy main');
select pg_temp.fd_assert((select count(*)=6 and min(qualifying_event_number)=1 and max(qualifying_event_number)=6 from public.leaderboard_tournament_season_memberships where season_id=(select season_id from bridge_badge_season) and scored_at is not null and voided_at is null),'continued season finalization requires six unique genuine slots');
select pg_temp.fd_assert((select count(*)=1 from public.leaderboard_seasons where is_active and official_bracket_type='pro' and finalized_at is null),'normal finalization must open exactly one fresh Pro successor');
select pg_temp.fd_assert(not exists(select 1 from public.leaderboard_season_champions where season_id=(select season_id from bridge_badge_season) and bracket_type<>'pro'),'new continued official champion snapshots must use the explicit Pro role');
select pg_temp.fd_assert((select count(*)>0 and bool_and(champion.bracket_type='pro' and champion.season_name=season.year::text||' Pro Season '||season.season_number::text)
 from public.leaderboard_public_season_champions champion join public.leaderboard_seasons season on season.id=champion.season_id
 where champion.season_id=(select season_id from bridge_badge_season)),'public finalized continuation archive must display the derived Pro season name and Pro championship role');
select pg_temp.fd_assert((select season.name=before.source_season_name and season.official_bracket_type='main'
 from public.leaderboard_seasons season join bridge_badge_season before on before.season_id=season.id),'public Pro championship heading must never rewrite the historical Main season name or stored family');
select pg_temp.fd_assert((select exists(select 1 from public.leaderboard_season_champions champion where champion.season_id=(select season_id from bridge_badge_season) and champion.player_id=pg_temp.fd_id('Pro-player',0,1) and champion.bracket_type='pro' and champion.final_rank=1 and champion.final_points=(select sum(event.points) from public.leaderboard_point_events event where event.season_id=champion.season_id and event.player_id=champion.player_id and event.bracket_type in ('main','pro')))),'champion snapshot must reflect the same combined genuine source ranking');
select pg_temp.fd_assert((select exists(select 1 from ironclad_private.leaderboard_official_season_standings standing where standing.season_id=(select season_id from bridge_badge_season) and standing.player_id=pg_temp.fd_id('Main-player',0,1) and standing.total_points=(select sum(event.points) from public.leaderboard_point_events event where event.season_id=standing.season_id and event.player_id=standing.player_id and event.bracket_type in ('main','pro')))),'continued ranking must retain the original Main competitor and genuine source points');
select pg_temp.fd_assert(season_campaigner_count=1 and first_season_campaigner_season_id=(select season_id from bridge_badge_season) and podium_finish_count=1 and champion_finish_count=1 and first_champion_season_id=(select season_id from bridge_badge_season) and first_champion_rank=1,'final season badge authority must include the genuinely earned Pro champion in the unchanged season UUID')
from public.get_player_badge_season_summary(pg_temp.fd_id('Pro-player',0,1));
select pg_temp.fd_assert(main_championship_count=5 and first_main_championship_bracket_type='main','legacy/future Main wins remain genuine Elite authority with the original earliest main source')
from public.get_player_badge_tournament_prestige_summary(pg_temp.fd_id('Main-player',0,1));
select pg_temp.fd_assert(season_campaigner_count=0 and podium_finish_count=0 and champion_finish_count=0,'one old Main event plus four future Main career wins must not become official Pro season badge authority')
from public.get_player_badge_season_summary(pg_temp.fd_id('Main-player',0,1));
select pg_temp.fd_assert(exists(select 1 from public.get_player_badge_season_authority_participants((select season_id from bridge_badge_season)) participant where participant.player_id=pg_temp.fd_id('Pro-player',0,1)),'final badge participant authority must include the Pro champion');
select pg_temp.fd_assert(exists(select 1 from public.get_player_badge_finalized_season_for_tournament(pg_temp.fd_id('event',6)) finalized where finalized.season_id=(select season_id from bridge_badge_season)),'completed Pro live badge path must resolve the continued finalized season');
select pg_temp.fd_assert(main_championship_count=0 and first_main_championship_bracket_type is null and championship_count=5 and triple_crown_bracket_count=0,'genuine Pro wins count generically and cannot substitute for Elite Main or Triple Crown')
from public.get_player_badge_tournament_prestige_summary(pg_temp.fd_id('Pro-player',0,1));

-- Future Main continues its own factual badge authority without an official slot.
select pg_temp.fd_create(7,'Main',1);
select pg_temp.fd_play(7,'Main');
select pg_temp.fd_assert(main_championship_count=1 and first_main_championship_bracket_type='main_progression' and championship_count=1 and triple_crown_bracket_count=1,'future Main remains an Elite Main source and only one Triple Crown division')
from public.get_player_badge_tournament_prestige_summary(pg_temp.fd_id('Main-player',1,1));
select pg_temp.fd_assert(podium_finish_count=0 and champion_finish_count=0,'future Main career must not receive an official season podium or champion')
from public.get_player_badge_season_summary(pg_temp.fd_id('Main-player',1,1));

select pg_temp.fd_assert(history.award=(select to_jsonb(award) from public.player_badge_awards award where award.id=pg_temp.fd_id('bridge-preserved-elite-award',1)) and
  history.reveal=(select to_jsonb(reveal) from public.player_badge_reveals reveal where reveal.id=pg_temp.fd_id('bridge-preserved-elite-reveal',1)) and
  history.notification=(select to_jsonb(notification) from public.notifications notification where notification.id=pg_temp.fd_id('bridge-preserved-elite-notification',1)) and
  history.point_events=(select jsonb_agg(to_jsonb(event) order by event.id) from public.leaderboard_point_events event where event.tournament_id=pg_temp.fd_id('event',1)) and
  history.membership=(select to_jsonb(membership) from public.leaderboard_tournament_season_memberships membership where membership.tournament_id=pg_temp.fd_id('event',1)) and
  history.settlements=(select jsonb_agg(to_jsonb(settlement) order by settlement.tournament_bracket_id) from public.leaderboard_division_settlements settlement join public.tournament_brackets bracket on bracket.id=settlement.tournament_bracket_id where bracket.tournament_id=pg_temp.fd_id('event',1)),
  'continuation/finalization must preserve original award IDs/evidence/timestamps/reveals/notifications/points/membership/settlement checksums')
from bridge_badge_history history;
rollback;
